// manifest.go is the committed description of what a project consumes from
// one OPC UA server: the tag bindings onto its address space, and the
// server's namespace table as it stood at import time. Generated by
// `naut opcua import`; validated offline in New so `naut check` and
// `naut build` pass with no server in sight.
//
// The YAML shapes carry NO yaml struct tags, so the on-disk keys are the
// lowercased Go field names ("nodeid", "scanclass") — modbus.Manifest's
// convention exactly, decoded with KnownFields(true) so a typo is an error
// rather than a silently dropped binding.
package opcua

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"regexp"
	"sort"
	"strings"

	"github.com/gopcua/opcua/ua"
	"gopkg.in/yaml.v3"
)

// Manifest is one project's OPC UA surface against one server.
type Manifest struct {
	// Namespaces is the server's namespace array when the manifest was
	// imported, index-aligned (entry 0 is always the OPC UA namespace).
	// Informational: the driver resolves each binding's Namespace URI
	// against the LIVE table at connect, because a server may renumber its
	// namespaces between restarts (Ignition does when providers are added).
	Namespaces []string
	Tags       []TagBinding
}

// TagBinding maps one nautilus tag onto one Variable node.
type TagBinding struct {
	// Name is the nautilus tag (what ST declares under VAR_EXTERNAL and Go
	// reads from the tag store).
	Name string
	// NodeID is the node as the server identified it at import, in the
	// standard string form: "ns=2;s=[default]Plant/Pump1/Speed",
	// "ns=3;i=1042", "ns=1;g=…", "ns=1;b=…".
	NodeID string
	// Namespace is the URI of the node's namespace. When set, the driver
	// looks the URI up in the server's live namespace array and rewrites
	// the ns= index before the first read — so a renumbering is survived
	// rather than silently reading someone else's node. Empty trusts the
	// index as written.
	Namespace string
	// Type is the OPC UA built-in type of the Variable's Value: Boolean
	// SByte Byte Int16 UInt16 Int32 UInt32 Int64 UInt64 Float Double String
	// DateTime. It decides what a write encodes as; reads deliver whatever
	// the server sends, coerced to nautilus scalars (ints → int64, floats →
	// float64, DateTime → unix milliseconds).
	Type string
	// Writable makes this an output tag: the runtime's writes propagate to
	// the server with the Write service.
	Writable bool
	// ScanClass names the poll group; "" is the default class and NoPoll
	// catalogs the tag without polling it. WithTagClass overrides this, so
	// generated manifests stay regenerable and policy lives in the project.
	ScanClass string
	// Desc is the node's Description (or DisplayName) as browsed — carried
	// here so `naut opcua tags` can re-derive the tag file, descriptions
	// included, without a server.
	Desc string
}

// ── scan classes ─────────────────────────────────────────────────────────

// DefaultClass is the scan class of every binding that isn't assigned one.
const DefaultClass = "default"

// NoPoll is the reserved scan class for tags that stay in the catalog but
// are never read — declared, visible in the manifest, inert on the wire.
const NoPoll = "none"

// ── types ────────────────────────────────────────────────────────────────

// TypeNames lists the built-in types a binding may declare, in OPC UA's
// numbering order (the DataType node ids i=1 … i=13).
var TypeNames = []string{
	"Boolean", "SByte", "Byte", "Int16", "UInt16", "Int32", "UInt32",
	"Int64", "UInt64", "Float", "Double", "String", "DateTime",
}

var typeByName = func() map[string]bool {
	m := map[string]bool{}
	for _, n := range TypeNames {
		m[n] = true
	}
	return m
}()

// ── YAML ─────────────────────────────────────────────────────────────────

// LoadManifest decodes an opcua_manifest.yaml. It does not validate — call
// Validate (New does) for the cross-checks, since a generator may want to
// load, edit and re-render a manifest that is not yet consistent.
func LoadManifest(r io.Reader) (Manifest, error) {
	var m Manifest
	dec := yaml.NewDecoder(r)
	dec.KnownFields(true) // a typo is an error, not a silently dropped binding
	if err := dec.Decode(&m); err != nil {
		if errors.Is(err, io.EOF) {
			return Manifest{}, fmt.Errorf("opcua: manifest is empty")
		}
		return Manifest{}, fmt.Errorf("opcua: manifest: %w", err)
	}
	return m, nil
}

// ParseManifest decodes a manifest from bytes — LoadManifest for callers
// that already hold the file (the project loader reads through an fs.FS).
func ParseManifest(data []byte) (Manifest, error) {
	return LoadManifest(bytes.NewReader(data))
}

// ── Validation ───────────────────────────────────────────────────────────

// Validate checks the manifest offline: names unique, node ids parse, types
// known. It is the whole of what `naut check` needs — no server is ever
// contacted. All findings are reported at once (errors.Join) so a generated
// manifest with three problems is three lines, not three edit-run cycles.
func (m Manifest) Validate() error {
	var errs []error
	seen := make(map[string]bool, len(m.Tags))
	for _, t := range m.Tags {
		if t.Name == "" {
			errs = append(errs, fmt.Errorf("tag binding on node %q: missing name", t.NodeID))
			continue
		}
		if seen[t.Name] {
			errs = append(errs, fmt.Errorf("duplicate tag name %q", t.Name))
			continue
		}
		seen[t.Name] = true
		if t.NodeID == "" {
			errs = append(errs, fmt.Errorf("tag %s: missing nodeid", t.Name))
		} else if err := checkNodeID(t.NodeID); err != nil {
			errs = append(errs, fmt.Errorf("tag %s: nodeid %q: %w", t.Name, t.NodeID, err))
		}
		if t.Type == "" {
			errs = append(errs, fmt.Errorf("tag %s: missing type (one of %s)", t.Name, strings.Join(TypeNames, " ")))
		} else if !typeByName[t.Type] {
			errs = append(errs, fmt.Errorf("tag %s: unknown type %q%s", t.Name, t.Type, didYouMean(t.Type, TypeNames)))
		}
	}
	if len(errs) == 0 {
		return nil
	}
	return errors.Join(errs...)
}

// nodeIDForm is the standard string form: an optional "ns=N;" then one of
// i= (numeric) s= (string) g= (GUID) b= (opaque, base64). gopcua's parser
// is lenient (bare text decodes as a string id in namespace 0), which is
// exactly the typo this check exists to catch.
var nodeIDForm = regexp.MustCompile(`^(ns=\d+;)?(i=\d+|s=.+|g=.+|b=.+)$`)

func checkNodeID(s string) error {
	if !nodeIDForm.MatchString(s) {
		return fmt.Errorf("want ns=N;i=… / s=… / g=… / b=…")
	}
	_, err := ua.ParseNodeID(s)
	return err
}

// Sorted returns a copy with the bindings ordered by name — what the
// generator renders, so a regenerated manifest diffs against the last.
func (m Manifest) Sorted() Manifest {
	out := m
	out.Tags = append([]TagBinding(nil), m.Tags...)
	sort.SliceStable(out.Tags, func(i, j int) bool { return out.Tags[i].Name < out.Tags[j].Name })
	return out
}

// didYouMean suggests the closest candidate for a mistyped name.
func didYouMean(name string, candidates []string) string {
	best, bestD := "", 3
	for _, c := range candidates {
		if d := editDistance(strings.ToLower(name), strings.ToLower(c)); d < bestD {
			best, bestD = c, d
		}
	}
	if best == "" {
		return ""
	}
	return " (did you mean " + best + "?)"
}

// editDistance is plain Levenshtein — the inputs are type names, short
// enough that the O(n·m) table is nothing.
func editDistance(a, b string) int {
	prev := make([]int, len(b)+1)
	cur := make([]int, len(b)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(a); i++ {
		cur[0] = i
		for j := 1; j <= len(b); j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev, cur = cur, prev
	}
	return prev[len(b)]
}
